namespace sv_4f72a9cfcd364cf8a868d481628c47be.Client.Models;

public sealed record Shipment(
    string TrackingNumber,
    string Status,
    string Location,
    DateTimeOffset EstimatedDelivery,
    IReadOnlyList<StatusUpdate> Updates);

public sealed record StatusUpdate(
    DateTimeOffset Timestamp,
    string Status,
    string Location);

using sv_4f72a9cfcd364cf8a868d481628c47be.Client.Models;

namespace sv_4f72a9cfcd364cf8a868d481628c47be.Client.Services;

public interface IShipmentService
{
    Task<Shipment> GetShipmentAsync(string trackingNumber, CancellationToken ct);
}

using sv_4f72a9cfcd364cf8a868d481628c47be.Client.Models;
using sv_4f72a9cfcd364cf8a868d481628c47be.Client.Services;

namespace sv_4f72a9cfcd364cf8a868d481628c47be.Services;

public sealed class ShipmentService : IShipmentService
{
    private static readonly Dictionary<string, Shipment> SeedData = new(StringComparer.OrdinalIgnoreCase)
    {
        ["TRK-001"] = new Shipment(
            TrackingNumber: "TRK-001",
            Status: "In Transit",
            Location: "Chicago, IL",
            EstimatedDelivery: new DateTimeOffset(2026, 6, 15, 17, 0, 0, TimeSpan.Zero),
            Updates: new List<StatusUpdate>
            {
                new(new DateTimeOffset(2026, 6, 10, 8, 0, 0, TimeSpan.Zero), "Picked Up", "New York, NY"),
                new(new DateTimeOffset(2026, 6, 11, 14, 30, 0, TimeSpan.Zero), "In Transit", "Philadelphia, PA"),
                new(new DateTimeOffset(2026, 6, 12, 9, 15, 0, TimeSpan.Zero), "In Transit", "Chicago, IL"),
            }),

        ["TRK-002"] = new Shipment(
            TrackingNumber: "TRK-002",
            Status: "Delivered",
            Location: "San Francisco, CA",
            EstimatedDelivery: new DateTimeOffset(2026, 6, 10, 12, 0, 0, TimeSpan.Zero),
            Updates: new List<StatusUpdate>
            {
                new(new DateTimeOffset(2026, 6, 7, 10, 0, 0, TimeSpan.Zero), "Picked Up", "Seattle, WA"),
                new(new DateTimeOffset(2026, 6, 8, 16, 0, 0, TimeSpan.Zero), "In Transit", "Portland, OR"),
                new(new DateTimeOffset(2026, 6, 9, 11, 0, 0, TimeSpan.Zero), "Out for Delivery", "San Francisco, CA"),
                new(new DateTimeOffset(2026, 6, 9, 15, 45, 0, TimeSpan.Zero), "Delivered", "San Francisco, CA"),
            }),

        ["TRK-003"] = new Shipment(
            TrackingNumber: "TRK-003",
            Status: "Processing",
            Location: "Dallas, TX",
            EstimatedDelivery: new DateTimeOffset(2026, 6, 18, 12, 0, 0, TimeSpan.Zero),
            Updates: new List<StatusUpdate>
            {
                new(new DateTimeOffset(2026, 6, 12, 6, 0, 0, TimeSpan.Zero), "Label Created", "Dallas, TX"),
            }),
    };

    public async Task<Shipment> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        await Task.Delay(1500, ct);

        if (SeedData.TryGetValue(trackingNumber, out var shipment))
        {
            return shipment;
        }

        throw new KeyNotFoundException($"Tracking number '{trackingNumber}' not found.");
    }
}

@page "/shipments/{TrackingNumber}"
@using sv_4f72a9cfcd364cf8a868d481628c47be.Client.Models
@using sv_4f72a9cfcd364cf8a868d481628c47be.Client.Services
@inject IShipmentService ShipmentService
@inject ILogger<ShipmentTracker> Logger
@implements IDisposable
@rendermode InteractiveAuto

<PageTitle>Shipment @TrackingNumber</PageTitle>

@if (_loading)
{
    <div class="loading-placeholder">
        <p><em>Loading shipment details for @TrackingNumber&hellip;</em></p>
    </div>
}
else if (_errorMessage is not null)
{
    <div class="error-container">
        <p class="error-message">@_errorMessage</p>
        <button @onclick="RetryLoad">Retry</button>
    </div>
}
else if (_shipment is not null)
{
    <h2>Shipment @_shipment.TrackingNumber</h2>
    <dl>
        <dt>Status</dt>
        <dd>@_shipment.Status</dd>
        <dt>Location</dt>
        <dd>@_shipment.Location</dd>
        <dt>Estimated Delivery</dt>
        <dd>@_shipment.EstimatedDelivery.ToString("f")</dd>
    </dl>

    <h3>Status Updates</h3>
    <table>
        <thead>
            <tr>
                <th>Time</th>
                <th>Status</th>
                <th>Location</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var update in _shipment.Updates)
            {
                <tr>
                    <td>@update.Timestamp.ToString("g")</td>
                    <td>@update.Status</td>
                    <td>@update.Location</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    [Parameter]
    public string TrackingNumber { get; set; } = default!;

    private Shipment? _shipment;
    private bool _loading;
    private string? _errorMessage;
    private CancellationTokenSource? _cts;

    protected override Task OnParametersSetAsync()
    {
        return LoadShipmentAsync();
    }

    private async Task LoadShipmentAsync()
    {
        // Cancel any in-flight request
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = new CancellationTokenSource();
        var ct = _cts.Token;

        _loading = true;
        _errorMessage = null;
        _shipment = null;

        try
        {
            _shipment = await ShipmentService.GetShipmentAsync(TrackingNumber, ct);
        }
        catch (OperationCanceledException) when (ct.IsCancellationRequested)
        {
            // Navigation changed or component disposed; do nothing.
            return;
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "Something went wrong loading shipment details. Please try again.";
        }
        finally
        {
            if (!ct.IsCancellationRequested)
            {
                _loading = false;
            }
        }
    }

    private Task RetryLoad() => LoadShipmentAsync();

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

